CREATE TYPE "NotificationChannel" AS ENUM ('IN_APP','EMAIL','SMS','PUSH','WHATSAPP');
CREATE TYPE "NotificationStatus" AS ENUM ('PENDING','SCHEDULED','PROCESSING','SENT','DELIVERED','FAILED','CANCELLED','SKIPPED');
CREATE TYPE "NotificationTemplateStatus" AS ENUM ('DRAFT','ACTIVE','PAUSED','ARCHIVED');
CREATE TYPE "NotificationDeliveryStatus" AS ENUM ('PENDING','SENT','DELIVERED','FAILED');
CREATE TYPE "NotificationKind" AS ENUM ('TRANSACTIONAL','MARKETING');
CREATE TABLE "NotificationTemplate" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"name" TEXT NOT NULL,"channel" "NotificationChannel" NOT NULL,"subject" TEXT,"body" TEXT NOT NULL,"variables" JSONB NOT NULL,"locale" TEXT NOT NULL DEFAULT 'tr-TR',"status" "NotificationTemplateStatus" NOT NULL DEFAULT 'DRAFT',"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"archivedAt" TIMESTAMP(3),FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE,FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "NotificationTemplate_businessId_id_key" ON "NotificationTemplate"("businessId","id");
CREATE UNIQUE INDEX "NotificationTemplate_businessId_name_locale_channel_key" ON "NotificationTemplate"("businessId","name","locale","channel");
CREATE INDEX "NotificationTemplate_businessId_status_channel_idx" ON "NotificationTemplate"("businessId","status","channel");
CREATE TABLE "Notification" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"customerId" TEXT,"userId" TEXT,"appointmentId" TEXT,"automationExecutionId" TEXT,"templateId" TEXT,"channel" "NotificationChannel" NOT NULL,"kind" "NotificationKind" NOT NULL DEFAULT 'TRANSACTIONAL',"recipient" TEXT NOT NULL,"subject" TEXT,"body" TEXT NOT NULL,"status" "NotificationStatus" NOT NULL DEFAULT 'PENDING',"scheduledAt" TIMESTAMP(3),"sentAt" TIMESTAMP(3),"correlationId" TEXT,"causationId" TEXT,"idempotencyKey" TEXT NOT NULL,"metadata" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"archivedAt" TIMESTAMP(3),FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE RESTRICT,FOREIGN KEY ("businessId","customerId") REFERENCES "BusinessCustomer"("businessId","id") ON DELETE RESTRICT,FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL,FOREIGN KEY ("businessId","appointmentId") REFERENCES "Appointment"("businessId","id") ON DELETE RESTRICT,FOREIGN KEY ("automationExecutionId") REFERENCES "AutomationExecution"("id") ON DELETE SET NULL,FOREIGN KEY ("businessId","templateId") REFERENCES "NotificationTemplate"("businessId","id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "Notification_businessId_id_key" ON "Notification"("businessId","id");
CREATE UNIQUE INDEX "Notification_businessId_idempotencyKey_key" ON "Notification"("businessId","idempotencyKey");
CREATE INDEX "Notification_businessId_status_channel_createdAt_idx" ON "Notification"("businessId","status","channel","createdAt");
CREATE INDEX "Notification_businessId_customerId_createdAt_idx" ON "Notification"("businessId","customerId","createdAt");
CREATE INDEX "Notification_businessId_appointmentId_idx" ON "Notification"("businessId","appointmentId");
CREATE TABLE "NotificationDelivery" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"notificationId" TEXT NOT NULL,"provider" TEXT NOT NULL,"providerMessageId" TEXT,"status" "NotificationDeliveryStatus" NOT NULL DEFAULT 'PENDING',"attempt" INTEGER NOT NULL,"errorCode" TEXT,"errorMessage" TEXT,"requestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"deliveredAt" TIMESTAMP(3),"failedAt" TIMESTAMP(3),"metadata" JSONB NOT NULL,FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE RESTRICT,FOREIGN KEY ("businessId","notificationId") REFERENCES "Notification"("businessId","id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "NotificationDelivery_notificationId_provider_attempt_key" ON "NotificationDelivery"("notificationId","provider","attempt");
CREATE INDEX "NotificationDelivery_businessId_status_requestedAt_idx" ON "NotificationDelivery"("businessId","status","requestedAt");
CREATE TABLE "NotificationPreference" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"customerId" TEXT,"userId" TEXT,"scopeKey" TEXT NOT NULL,"channel" "NotificationChannel" NOT NULL,"transactionalEnabled" BOOLEAN NOT NULL DEFAULT true,"marketingEnabled" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE,FOREIGN KEY ("businessId","customerId") REFERENCES "BusinessCustomer"("businessId","id") ON DELETE CASCADE,FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "NotificationPreference_scope_channel_key" ON "NotificationPreference"("businessId","scopeKey","channel");
CREATE INDEX "NotificationPreference_businessId_customerId_channel_idx" ON "NotificationPreference"("businessId","customerId","channel");
CREATE INDEX "NotificationPreference_businessId_userId_channel_idx" ON "NotificationPreference"("businessId","userId","channel");
CREATE TABLE "NotificationProviderConfig" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"channel" "NotificationChannel" NOT NULL,"provider" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT false,"config" JSONB NOT NULL,"secretReference" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "NotificationProviderConfig_business_channel_provider_key" ON "NotificationProviderConfig"("businessId","channel","provider");
CREATE INDEX "NotificationProviderConfig_business_enabled_channel_idx" ON "NotificationProviderConfig"("businessId","enabled","channel");
